/**
 * Build the central module for all options' interfaces
 */

/* global console:readonly */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { lsFiles } from 'lsfnd';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.join(__dirname, '..');
const optionsDir = path.join(rootDir, 'src', 'core', 'internal', 'interfaces', 'options');
const targetFile = path.join(optionsDir, 'index.ts');

const headerFile = [
  '// ! WARNING: DO NOT EDIT THIS MODULE MANUALLY!',
  `// This module is auto-generated by "${path.relative(rootDir, __filename)}"`,
  '',  // A gap between header file and exports
];

async function build() {
  // Get the setup files
  const files = await lsFiles(optionsDir, {
    match: /\.ts$/,
    absolute: false,
    recursive: false,
    exclude: /index\.ts$/,
    basename: true
  });
  const resolvedFiles = files.map(file => file.replace(/\.ts$/, '.js'));
  const moduleContentList = [
    ...headerFile,
    // Exports
    ...resolvedFiles.map(file => {
      return `export type * from './${file}';`;
    })
  ]

  // Generate the module
  await fs.promises.writeFile(targetFile, moduleContentList.join('\n') + '\n', {
    encoding: 'utf-8',
    flag: 'w'
  });
  console.log(
    `Generated ${path.relative(rootDir, targetFile)} for modules:\n`
    + files.map(file => `> ${path.relative(rootDir, path.join(optionsDir, file))}`).join('\n')
  );
}

await build();
